import type { CSSProperties } from "react";
import "./masked-line-reveal.css";

export interface MaskedLineRevealProps {
  lines: string[];
  as?: "h1" | "h2" | "h3" | "p";
  className?: string;
}

export function MaskedLineReveal({
  lines,
  as: Tag = "h2",
  className = "",
}: MaskedLineRevealProps) {
  const visibleLines = lines.map((line) => line.trim()).filter(Boolean);

  if (visibleLines.length === 0) return null;

  return (
    <Tag
      className={`tb-masked-line-reveal ${className}`.trim()}
      aria-label={visibleLines.join(" ")}
    >
      <span aria-hidden="true">
        {visibleLines.map((line, index) => (
          <span className="tb-masked-line-reveal__line" key={`${line}-${index}`}>
            <span
              className="tb-masked-line-reveal__text"
              style={{ "--tb-mlr-index": index } as CSSProperties}
            >
              {line}
            </span>
          </span>
        ))}
      </span>
    </Tag>
  );
}

export default MaskedLineReveal;

.tb-masked-line-reveal {
  margin: 0;
  color: #171816;
  font: 650 clamp(2.1rem, 8cqi, 6.8rem) / 0.94 system-ui, sans-serif;
  letter-spacing: -0.065em;
}

.tb-masked-line-reveal__line {
  display: block;
  overflow: hidden;
  padding-block: 0.08em;
}

.tb-masked-line-reveal__text {
  display: block;
  animation: tb-masked-line-reveal-in 480ms cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc(var(--tb-mlr-index) * 70ms);
}

@keyframes tb-masked-line-reveal-in {
  from {
    opacity: 0;
    transform: translateY(78%);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .tb-masked-line-reveal__text {
    animation: none;
  }
}

@media (forced-colors: active) {
  .tb-masked-line-reveal {
    color: CanvasText;
  }
}
